from pydantic import BaseModel, Field


# ============================================================
# CREATE PATIENT
# ============================================================

class PatientCreate(BaseModel):

    # Patient ID is generated by the backend.
    # The frontend does NOT need to provide it.

    age: int = Field(
        ...,
        ge=0,
        le=120,
    )

    gender: str

    state: str

    bpl_card: bool = False

    insurance_type: str | None = None

    comorbidity_count: int = Field(
        default=0,
        ge=0,
    )

    prev_admissions: int = Field(
        default=0,
        ge=0,
    )


# ============================================================
# UPDATE PATIENT
# ============================================================

class PatientUpdate(BaseModel):
    age: int | None = Field(default=None, ge=0, le=120)
    gender: str | None = None
    state: str | None = None
    bpl_card: bool | None = None
    insurance_type: str | None = None
    comorbidity_count: int | None = Field(default=None, ge=0)
    prev_admissions: int | None = Field(default=None, ge=0)


# ============================================================
# PATIENT RESPONSE
# ============================================================

class PatientResponse(BaseModel):

    id: int

    patient_id: str

    age: int

    gender: str

    state: str

    bpl_card: bool

    insurance_type: str | None

    comorbidity_count: int

    prev_admissions: int

    class Config:
        from_attributes = True